from ta5g_iphy import ta5g_iphy
from ta5g_enb import ta5g_enb
from ta5g_egate import ta5g_egate
from ta5g_testline_management import ta5g_testline_management
from ta5g_commissioning import ta5g_commissioning
from .setups_and_teardowns import SetupsAndTeardowns


class SetupConfiguration(object):
    def __init__(self):
        self.ta_egate_instance = ta5g_egate()
        self.ta_commissioning_instance = ta5g_commissioning()
        self.ta_iphy_instance = ta5g_iphy()
        self.ta_enb_instance = ta5g_enb()
        self.ta_vm_management_instance = ta5g_testline_management()

    def testline_configuration(
        self,
        lua_cfg_filepath,
        iphy_xml_filepath,
        scfc_filename,
        swconfig_flags_list=[],
        output_dirpath=None,
        remote_host=None,
        start_simenb_interface=True,
        start_default_logging=True,
        perform_full_commissioning=True,
        perform_delta_commissioning=False,
        reach_onair=True,
        bts_id="1"
    ):
        if start_simenb_interface:
            self.ta_vm_management_instance.start_default_simulated_enb_interface()
        self.ta_enb_instance.backup_and_modify_swconfig_file(swconfig_flags_list, output_dirpath, None)
        self.ta_iphy_instance.update_and_put_iphy_xml(iphy_xml_filepath, output_dirpath=output_dirpath)
        self.ta_iphy_instance.reset_wts_and_wait_for_enb_to_reach_configured_state()
        SetupsAndTeardowns().start_default_logging(output_dirpath=output_dirpath)
        if perform_delta_commissioning:
            self.ta_commissioning_instance.find_scfc_and_send_delta_commissioning(
                scfc_filename, output_dirpath, remote_host
            )
        elif perform_full_commissioning:
            self.ta_commissioning_instance.find_scfc_and_fix_and_send_full_commissioning(
                scfc_filename=scfc_filename, remote_host=remote_host, output_dirpath=output_dirpath, bts_id=bts_id
            )
        if reach_onair:
            self.ta_egate_instance.reach_onair(lua_cfg_filepath, output_dirpath)
        if not start_default_logging:
            SetupsAndTeardowns().stop_default_logging(output_dirpath)
